def bbox(grid, v):
    """The (top, bottom, left, right) bounding box of all cells of color v, or None."""
    cs = [(i, j) for i, row in enumerate(grid) for j, x in enumerate(row) if x == v]
    if not cs:
        return None
    rs = [i for i, _ in cs]; js = [j for _, j in cs]
    return min(rs), max(rs), min(js), max(js)

def dominant_color(grid):
    """The most frequent nonzero color in the grid."""
    from collections import Counter
    return Counter(v for row in grid for v in row if v).most_common(1)[0][0]

def other_color(grid, main):
    """The least frequent nonzero color that is not main (the minority shape's color)."""
    from collections import Counter
    c = [v for v, _ in Counter(v for row in grid for v in row if v).most_common() if v != main]
    return c[-1]

def keep_color(grid, v):
    """The grid with every cell not of color v zeroed."""
    return [[x if x == v else 0 for x in row] for row in grid]

def mirror_toward(grid, main, other):
    """The main-color shape plus its mirror image across the axis adjacent to it on the side where the other shape lies (horizontal if they are side by side, vertical if stacked); everything else zeroed."""
    h, w = len(grid), len(grid[0])
    t, b, l, r = bbox(grid, main)
    t2, b2, l2, r2 = bbox(grid, other)
    out = keep_color(grid, main)
    if r2 < l or l2 > r:
        if l2 > r:  # other is right: mirror rightwards
            for i in range(h):
